class Solution {
    using LL = long long;
    vector<LL> shortest(int start, const vector<vector<pair<int,LL>>>& g) {
        const LL INF = (1LL << 62);
        vector<LL> d(g.size(), INF);
        priority_queue<pair<LL,int>, vector<pair<LL,int>>,
                       greater<pair<LL,int>>> pq;
        d[start] = 0;
        pq.push({0, start});
        while (!pq.empty()) {
            auto top = pq.top(); pq.pop();
            LL du = top.first;
            int u = top.second;
            if (du != d[u]) continue;
            for (auto e : g[u]) {
                if (d[e.first] > du + e.second) {
                    d[e.first] = du + e.second;
                    pq.push({d[e.first], e.first});
                }
            }
        }
        return d;
    }
public:
    vector<int> minCost(int n, vector<int>& prices,
                        vector<vector<int>>& roads) {
        vector<vector<pair<int,LL>>> empty(n), loaded(n);
        for (auto& e : roads) {
            int u = e[0], v = e[1];
            LL w = e[2], t = e[3];
            empty[u].push_back({v, w});
            empty[v].push_back({u, w});
            loaded[u].push_back({v, w * t});
            loaded[v].push_back({u, w * t});
        }
        vector<int> ans(n);
        for (int i = 0; i < n; ++i) {
            auto a = shortest(i, empty);
            auto b = shortest(i, loaded);
            LL best = prices[i];
            for (int j = 0; j < n; ++j) {
                if (a[j] < (1LL << 60) && b[j] < (1LL << 60))
                    best = min(best, a[j] + b[j] + prices[j]);
            }
            ans[i] = (int)best;
        }
        return ans;
    }
};
